def download_image(url, folder, filename, force=False):
    from django.conf import settings

    media_root = getattr(settings, "MEDIA_ROOT", "")
    if not media_root:
        raise RuntimeError("MEDIA_ROOT is not configured.")

    target_dir = os.path.join(media_root, folder)
    os.makedirs(target_dir, exist_ok=True)

    clean_name = re.sub(r"[^a-zA-Z0-9_-]+", "-", filename).strip("-").lower()
    target_path = os.path.join(target_dir, clean_name + ".jpg")

    if os.path.exists(target_path) and not force:
        return os.path.relpath(target_path, media_root).replace("\\", "/")

    request = urllib.request.Request(url, headers=IMAGE_HEADERS)
    with urllib.request.urlopen(request, timeout=30) as response:
        content = response.read()

    with open(target_path, "wb") as image_file:
        image_file.write(content)

    return os.path.relpath(target_path, media_root).replace("\\", "/")


class Command(BaseCommand):
    help = "Add rich VOYAGE destinations, tours and travel fun facts."

    def add_arguments(self, parser):
        parser.add_argument(
            "--refresh-images",
            action="store_true",
            help="Redownload local Destination/FunFact images.",
        )

    @transaction.atomic
    def handle(self, *args, **options):
        refresh_images = options["refresh_images"]

        self.stdout.write(self.style.WARNING("Seeding VOYAGE travel content..."))

        destination_map = {}
        created_destinations = updated_destinations = 0
        created_tours = updated_tours = 0
        created_funfacts = updated_funfacts = 0
        failed_images = 0

        # DESTINATIONS
        for data in DESTINATIONS:
            slug = slugify(data["name"])
            image_url, hover_url = DESTINATION_IMAGE_PAIRS[slug]

            image_path = hover_path = None

            try:
                image_path = download_image(
                    image_url, "destinations", f"{slug}-main", refresh_images
                )
                hover_path = download_image(
                    hover_url, "destinations/hover", f"{slug}-hover", refresh_images
                )
            except Exception as exc:
                failed_images += 1
                self.stdout.write(
                    self.style.WARNING(f"  ! Image download failed for {data['name']}: {exc}")
                )

            defaults = {
                "country": data["country"],
                "state": data["state"],
                "city": data["city"],
                "description": data["description"],
                "hero_image": image_url,
                "best_time_to_travel": data["best_time_to_travel"],
                "weather": data["weather"],
                "rating": Decimal(data["rating"]),
                "latitude": data["latitude"],
                "longitude": data["longitude"],
                "nearby_places": data["nearby_places"],
                "reviews": data["reviews"],
                "related_tours_text": data["related_tours_text"],
                "is_featured": data["is_featured"],
                "order": data["order"],
            }

            if image_path:
                defaults["image"] = image_path
            if hover_path:
                defaults["hover_image"] = hover_path

            obj, created = Destination.objects.update_or_create(
                slug=slug,
                defaults=defaults,
            )
            destination_map[data["name"]] = obj

            if created:
                created_destinations += 1
                self.stdout.write(self.style.SUCCESS(f"  + Destination: {data['name']}"))
            else:
                updated_destinations += 1
                self.stdout.write(f"  ↻ Destination refreshed: {data['name']}")

        # TOURS
        for data in TOURS:
            slug = slugify(data["name"])
            destination_objects = [
                destination_map[name]
                for name in data["destination_names"]
                if name in destination_map
            ]

            defaults = {
                "summary": data["summary"],
                "duration": data["duration"],
                "duration_days": data["duration_days"],
                "price_per_person": Decimal(data["price_per_person"]),
                "budget_range": data["budget_range"],
                "transport_modes": data["transport_modes"],
                "hotels": data["hotels"],
                "meals": data["meals"],
                "guides": data["guides"],
                "seats_available": data["seats_available"],
                "max_capacity": data["max_capacity"],
                "overview": data["overview"],
                "itinerary": data["itinerary"],
                "included_items": data["included_items"],
                "excluded_items": data["excluded_items"],
                "gallery": data["gallery"],
                "reviews": data["reviews"],
                "rating": Decimal(data["rating"]),
                "hero_image": data["hero_image"],
                "image": data["image"],
                "is_featured": data["is_featured"],
                "order": data["order"],
            }

            tour, created = Tour.objects.update_or_create(
                slug=slug,
                defaults=defaults,
            )
            tour.destinations.set(destination_objects)

            if created:
                created_tours += 1
                self.stdout.write(self.style.SUCCESS(f"  + Tour: {data['name']}"))
            else:
                updated_tours += 1
                self.stdout.write(f"  ↻ Tour refreshed: {data['name']}")

        # FUN FACTS
        for data in FUN_FACTS:
            try:
                image_path = download_image(
                    data["image"],
                    "funfacts",
                    slugify(data["title"]),
                    refresh_images,
                )
            except Exception as exc:
                image_path = None
                failed_images += 1
                self.stdout.write(
                    self.style.WARNING(f"  ! Fun fact image failed for {data['title']}: {exc}")
                )

            defaults = {
                "description": data["description"],
                "emoji": data["emoji"],
                "order": data["order"],
            }
            if image_path:
                defaults["image"] = image_path

            obj, created = FunFact.objects.update_or_create(
                title=data["title"],
                defaults=defaults,
            )

            if created:
                created_funfacts += 1
                self.stdout.write(self.style.SUCCESS(f"  + Fun fact: {data['title']}"))
            else:
                updated_funfacts += 1
                self.stdout.write(f"  ↻ Fun fact refreshed: {data['title']}")

        self.stdout.write("")
        self.stdout.write(self.style.SUCCESS("VOYAGE seed complete."))
        self.stdout.write(
            f"Destinations: {created_destinations} added, {updated_destinations} refreshed"
        )
        self.stdout.write(f"Tours:        {created_tours} added, {updated_tours} refreshed")
        self.stdout.write(
            f"Fun facts:    {created_funfacts} added, {updated_funfacts} refreshed"
        )

        if failed_images:
            self.stdout.write(
                self.style.WARNING(
                    f"Image downloads with errors: {failed_images}. "
                    "Check your internet connection and rerun with --refresh-images."
                )
            )
